  const b=crmBridge(),workspaceId=b.workspace.id,domain=crmDomain(candidate.domain||candidate.website);const listed=await b.listCrmCompanies({q:domain,limit:20});if(workspaceId!==b.workspace?.id)return {ok:false,error:"Workspace changed; retry in the selected workspace"};if(!listed.ok)return listed;
  let company=(listed.companies||[]).find(row=>crmDomain(row.normalized_domain||row.website)===domain)||null;
  if(!company&&!create)return {ok:true,company:null};
  if(!company){const payload=window.LeadIntelCrm?.mapLocalPipelineItemToCrm(candidate);if(!payload)return {ok:false,error:"CRM mapper unavailable"};const saved=await b.saveCrmCompany(payload);if(!saved.ok)return saved;company=saved.company;}
  return {ok:true,company};
