function showStep(step){if(window.LeadIntelCustomerNavigation?.setStep&&window.LeadIntelCustomerNavigation.setStep(step)!==false){window.LeadIntelJourney?.refresh?.();return;}document.querySelectorAll(".step-view").forEach(el=>el.classList.toggle("active",Number(el.dataset.step)===step));document.querySelectorAll("[data-step-marker]").forEach(el=>{const n=Number(el.dataset.stepMarker);el.classList.toggle("active",n===step);el.classList.toggle("complete",n<step);});persistMainStep(step);window.LeadIntelJourney?.refresh?.();window.scrollTo({top:0,behavior:"smooth"});}
