function continueFromCompanies(){
  const stage=Number(q("continue-to-outreach")?.dataset.journeyStage)||5;
  if(stage===6&&window.LeadIntelDiscoveryUI?.continueToMessages){window.LeadIntelDiscoveryUI.continueToMessages();return;}
  if(window.LeadIntelJourney?.openWorkflowStage){window.LeadIntelJourney.openWorkflowStage(stage);return;}
  if(stage===5){window.LeadIntelDiscoveryUI?.open?.({focus:"buyers"});return;}
  showOutreachStep();
}
function backToDiscovery(){try{const meta=readJson(DISCOVERY_META_KEY);localStorage.setItem(DISCOVERY_META_KEY,JSON.stringify({...meta,activeJourneyStage:5,visibleStep:5}));}catch{}if(window.LeadIntelJourney?.openWorkflowStage){window.LeadIntelJourney.openWorkflowStage(5);return;}if(window.LeadIntelDiscoveryUI?.open){window.LeadIntelDiscoveryUI.open({focus:"buyers"});return;}showStep(5);}
function ensureSelection(){const list=pipeline();if(!list.length){outreach.selectedDomain="";saveOutreach();return;}if(!list.some(x=>x.domain===outreach.selectedDomain))outreach.selectedDomain=list[0].domain;saveOutreach();}

async function officialScrape(candidate){
  const response=await fetch(`${INTELLIGENCE_PROXY}/firecrawl-scrape`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({url:candidate.website,formats:["markdown"],onlyMainContent:true,timeout:30000})});
  const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.error||`Official site returned ${response.status}`);
  return LeadIntelOutreach.normalizeDossierResearchResults(payload,{domain:candidate.domain,sourceType:"official",url:candidate.website});
}
async function dossierSearch(meta){
  const response=await fetch(`${INTELLIGENCE_PROXY}/firecrawl-search`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({query:meta.query,limit:MAX_DOSSIER_RESULTS_PER_QUERY,scrapeOptions:{formats:["markdown"]}}),signal:meta.signal});
  const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.error||`Dossier search returned ${response.status}`);
  return LeadIntelOutreach.normalizeDossierResearchResults(payload,{domain:meta.domain,sourceType:"search"});
}
function cancelPendingScriptGeneration(){
  scriptGenerationRequest++;if(typeof studioGenerationBusy!=='undefined')studioGenerationBusy=false;const current=currentItem();if(current?.localizationStatus==='running'){upsertItem({...current,localizationStatus:'error',localizationApprovalBlocked:true,localizationMessage:'Generation was interrupted by a selection change. Regenerate this package before approval.'});}
}
async function prepareLocalizedItem(item,campaign,candidate){
  if(item.channel==='linkedin'){
    const request=++scriptGenerationRequest,domain=item.domain,bridge=crmBridge(),workspace=bridge?.session?.authenticated?bridge.workspace?.id:'';
    if(domain!==outreach.selectedDomain)return null;
    const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),30000);
    upsertItem({...item,localizationStatus:'running',localizationApprovalBlocked:true,localizationMessage:'Writing an evidence-based LinkedIn draft…'});renderDossier();
    let next;
    try{
      if(!workspace)throw new Error('Sign in to generate an AI draft');
      const contact=item.dossier?.people?.find(person=>person.id===item.selectedPersonId)||{},main=mainState();
      const prompt=LeadIntelOutreach.linkedInDraftPrompt(item.dossier,contact,main.profile||{},campaign,contentLanguage());
      const response=await fetch(`https://leadintel-api.edgars-7e7.workers.dev/api/ai/generate?workspace_id=${encodeURIComponent(workspace)}`,{method:'POST',credentials:'include',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({...prompt,task:'outreach-generation',max_output_tokens:600}),signal:controller.signal});
      const result=await response.json();if(!response.ok)throw new Error(result.error||'AI generation unavailable');
      const draft=LeadIntelOutreach.parseLinkedInDraft(result.text,item.dossier);
      next={...item,drafts:{...item.drafts,linkedinMessage:draft.message,scriptContext:{...item.drafts.scriptContext,eventSourceUrl:draft.eventSourceUrl}},localizationStatus:'complete',localizationApprovalBlocked:false,localizationMessage:'AI draft based on company evidence · review before copying'};
    }catch(error){next={...item,localizationStatus:'error',localizationApprovalBlocked:false,localizationMessage:'Source-based template shown; AI generation incomplete: '+(error.name==='AbortError'?'Request timed out':error.message)};}
    finally{clearTimeout(timeout);}
    if(request!==scriptGenerationRequest||domain!==outreach.selectedDomain||workspace!==(crmBridge()?.session?.authenticated?crmBridge()?.workspace?.id:''))return null;
    return next;
  }
  const request=++scriptGenerationRequest,domain=item.domain,bridge=crmBridge(),workspace=bridge?.session?.authenticated?bridge?.workspace?.id:'';if(domain!==outreach.selectedDomain)return null;if(item.researchStatus==='running')item={...item,researchStatus:item.dossier?.evidence?.length?'partial':'error'};const pending={...item,localizationStatus:item.drafts?.requiresAiLocalization?'running':'checking',localizationApprovalBlocked:true,localizationMessage:'Resolving recipient language…'};upsertItem(pending);renderDossier();
  const result=await LeadIntelOutreachLocalization.prepareCampaignDrafts({root:window,workspace,drafts:item.drafts,scenario:campaign,candidate:candidate||{},dossier:item.dossier||{},languageService:LeadIntelContentLanguage});
  if(request!==scriptGenerationRequest||domain!==outreach.selectedDomain||workspace!==(crmBridge()?.session?.authenticated?crmBridge()?.workspace?.id:''))return null;
  return {...item,drafts:result.drafts,campaignScenario:{...campaign,resolvedLanguage:result.provenance.language,languageSource:result.provenance.selectionSource},localizationStatus:result.status,localizationApprovalBlocked:result.approvalBlocked,localizationMessage:result.message,localizationProvenance:result.provenance};
}
async function buildDossier(){
  const candidate=selectedCandidate();if(!candidate){toast("Choose a saved pipeline company");return;}
  if(crmAuthenticated()&&(!handoffContact||handoffContact.domain!==candidate.domain||!candidate.people?.some(p=>p.id===handoffContact.personId&&p.kept))){toast('Save a buyer and confirm the selected contact channel in Buyers before creating content.');backToDiscovery();return;}
  const researchRequest=++scriptGenerationRequest,workspaceId=crmBridge()?.workspace?.id,main=mainState();let item=currentItem()||{domain:candidate.domain,company:candidate.company,drafts:{tone:"consultative",emailSubject:"",emailBody:"",linkedinMessage:"",callOpener:"",followUp:"",objectionReply:""},approved:false};
  item=LeadIntelOutreach.invalidateOutreachApproval({...item,channel:handoffContact?.channel||'email',company:candidate.company,researchStatus:"running"});upsertItem(item);renderAll();
  const research=[];let failures=0;try{research.push(...await officialScrape(candidate));}catch{failures++;}
  const queries=LeadIntelOutreach.buildDossierSearchQueries(candidate,main.profile||{},main.market||{},MAX_DOSSIER_SEARCH_QUERIES);for(const meta of queries){try{research.push(...await dossierSearch(meta));}catch{failures++;}}
  if(researchRequest!==scriptGenerationRequest||candidate.domain!==outreach.selectedDomain||workspaceId!==crmBridge()?.workspace?.id)return;
  if(handoffContact?.channel==='linkedin'&&!window.LeadIntelDiscovery.confirmedLinkedInBuyer(candidate.people.find(p=>p.id===handoffContact.personId),candidate,readJson(DISCOVERY_META_KEY).scriptBuyer,workspaceId)){toast('LinkedIn selection changed. Confirm it again in Buyers.');return;}
  const language=contentLanguage(),campaign=activeCampaignScenario();const dossierCandidate=handoffContact&&handoffContact.domain===candidate.domain?{...candidate,people:(candidate.people||[]).filter(p=>handoffContact.channel!=='linkedin'||p.id===handoffContact.personId).map(p=>p.id===handoffContact.personId?{...p,...handoffContact.contact,id:p.id,name:handoffContact.contact.name||p.name,email:handoffContact.contact.work_email||handoffContact.contact.normalized_email}:p)}:candidate;let dossier=LeadIntelOutreach.buildOpportunityDossier(dossierCandidate,main.profile||{},main.market||{},research,language);const choice=readJson(DISCOVERY_META_KEY).scriptBuyer;const contact=dossierCandidate.people?.find(p=>p.id===choice?.personId)||dossierCandidate.people?.[0]||null;
  item=LeadIntelOutreach.invalidateOutreachApproval({...item,dossier,campaignScenario:campaign,researchStatus:research.length?(failures?"partial":"complete"):"error",researchAt:new Date().toISOString(),selectedPersonId:contact?.id||"",drafts:LeadIntelOutreach.buildOutreachDrafts(dossier,contact,main.profile||{},campaign.tone||"consultative",language,campaign),contentLanguage:language});item=await prepareLocalizedItem(item,campaign,candidate);if(!item)return;upsertItem(item);
  const crm=await syncCrmActivity(candidate,{activity:{id:crmActivityId("dossier-built",candidate.domain,item.researchAt),type:"dossier.built",summary:"Opportunity dossier built",occurred_at:item.researchAt,metadata:{evidence_count:dossier.evidence?.length||0,research_status:item.researchStatus,script_package:LeadIntelOutreach.buildCrmScriptSnapshot(item)}}});renderAll();
  const baseMessage=research.length?`Dossier built from ${dossier.evidence.length} evidence source${dossier.evidence.length===1?"":"s"}${failures?" · some research unavailable":""}`:"Dossier kept conservative because public research was unavailable";toast(!crm.ok?`${baseMessage} · CRM sync unavailable`:baseMessage);
}
function selectedContact(item){if(!item?.dossier?.people?.length)return null;return item.dossier.people.find(p=>p.id===item.selectedPersonId)||item.dossier.people[0];}
async function regenerateDrafts(){const current=currentItem();if(!current?.dossier)return;if(current.contextNeedsRefresh)return buildDossier();const campaign={...activeCampaignScenario(),tone:q("outreach-tone").value};let item=LeadIntelOutreach.invalidateOutreachApproval(current);item.campaignScenario=campaign;item.selectedPersonId=q("outreach-contact-select").value;item.drafts=LeadIntelOutreach.buildOutreachDrafts(item.dossier,selectedContact(item),mainState().profile||{},campaign.tone,contentLanguage(),campaign);item.contentLanguage=contentLanguage();item=await prepareLocalizedItem(item,campaign,selectedCandidate()||item.dossier);if(!item)return;upsertItem(item);renderDossier();toast(item.localizationApprovalBlocked?item.localizationMessage:"Campaign scripts regenerated · approval required");return item;}
async function confirmOutreachLanguage(){const current=currentItem(),language=q("outreach-email-language")?.value;if(!current?.dossier||!language)return;const campaign={...(current.campaignScenario||activeCampaignScenario()),tone:q("outreach-tone").value,language,resolvedLanguage:language,languageSource:'manual'};let item=LeadIntelOutreach.invalidateOutreachApproval(current);item.campaignScenario=campaign;item.selectedPersonId=q("outreach-contact-select").value;item.drafts=LeadIntelOutreach.buildOutreachDrafts(item.dossier,selectedContact(item),mainState().profile||{},campaign.tone,contentLanguage(),campaign);item=await prepareLocalizedItem(item,campaign,selectedCandidate()||item.dossier);if(!item)return;upsertItem(item);renderDossier();toast(item.localizationApprovalBlocked?item.localizationMessage:`Recipient email language confirmed · ${LeadIntelContentLanguage.EMAIL_LANGUAGES?.[language]||language}`);}
