 return (LeadIntelMessageStudio.resolveApprovedSubject(studio,studioMessageContext(item,candidate),studio.essentials)||LeadIntelMessageStudio.resolvedSubject(studio,studioMessageContext(item,candidate),studio.essentials))||'';
