   const target=(outreach.items||[]).find(i=>i.domain===choice.domain)||(currentItem()?.domain===choice.domain?currentItem():null),hasDraft=target?.channel==='linkedin'&&target.selectedPersonId===person.id&&target.drafts?.linkedinMessage?.trim();
   let saved=null;if(!hasDraft&&!LeadIntelOutreach.savedBuyerDraft(outreach,candidate.domain,person.id,'linkedin')?.drafts?.linkedinMessage)saved=await savedLinkedInCrmDraft(companyRecord,candidate.domain,person.id,choice.workspaceId);
   if(!active())return false;
