   handoffContact={domain:choice.domain,personId:choice.personId,channel:'linkedin',contact:{name:person.publicName||person.name,linkedin_url:choice.linkedinUrl}};
   if(saved)upsertItem(saved);saveOutreach();prepareStudioBuyer(candidate,person);showOutreachStep();
